<?php
$config=require __DIR__.'/saki-config.php';
$pdo=new PDO("mysql:host={$config['db_host']};dbname={$config['db_name']};charset=utf8mb4",$config['db_user'],$config['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$rows=[['JO','الأردن','🇯🇴'],['SA','السعودية','🇸🇦'],['AE','الإمارات العربية المتحدة','🇦🇪'],['EG','مصر','🇪🇬'],['IQ','العراق','🇮🇶'],['SY','سوريا','🇸🇾'],['PS','فلسطين','🇵🇸'],['LB','لبنان','🇱🇧'],['KW','الكويت','🇰🇼'],['QA','قطر','🇶🇦'],['BH','البحرين','🇧🇭'],['OM','عُمان','🇴🇲'],['YE','اليمن','🇾🇪'],['MA','المغرب','🇲🇦'],['DZ','الجزائر','🇩🇿'],['TN','تونس','🇹🇳'],['LY','ليبيا','🇱🇾'],['SD','السودان','🇸🇩'],['TR','تركيا','🇹🇷'],['US','الولايات المتحدة','🇺🇸'],['GB','المملكة المتحدة','🇬🇧'],['CA','كندا','🇨🇦'],['DE','ألمانيا','🇩🇪'],['FR','فرنسا','🇫🇷'],['IT','إيطاليا','🇮🇹'],['ES','إسبانيا','🇪🇸'],['IN','الهند','🇮🇳'],['PK','باكستان','🇵🇰'],['ID','إندونيسيا','🇮🇩'],['MY','ماليزيا','🇲🇾']];
$q=$pdo->prepare('INSERT INTO countries (code,name,name_ar,flag) VALUES (:c,:n,:a,:f) ON DUPLICATE KEY UPDATE name=VALUES(name),name_ar=VALUES(name_ar),flag=VALUES(flag)');foreach($rows as $r)$q->execute([':c'=>$r[0],':n'=>$r[1],':a'=>$r[1],':f'=>$r[2]]);echo json_encode(['ok'=>true,'count'=>count($rows)]);
